document.querySelectorAll('form[data-print-form]').forEach((form)=>{form.addEventListener('submit',()=>{const next=form.dataset.thanks;if(next){let redirect=form.querySelector('input[name="_next"]');if(!redirect){redirect=document.createElement('input');redirect.type='hidden';redirect.name='_next';form.appendChild(redirect)}redirect.value=new URL(next,window.location.href).href}})});document.querySelectorAll('[data-copy]').forEach((button)=>{button.addEventListener('click',async()=>{const value=button.dataset.copy||'';try{await navigator.clipboard.writeText(value);button.textContent='Copied';setTimeout(()=>{button.textContent='Copy'},1400)}catch{button.textContent='Copy manually'}})});document.querySelectorAll('.language-switcher a').forEach((link)=>{link.addEventListener('click',()=>{try{localStorage.setItem('preferredLocale',new URL(link.href,window.location.href).pathname.split('/')[1]||'en')}catch{}})});(()=>{const header=document.querySelector('.header');if(!header)return;const top=header.querySelector('.top');if(!top||top.dataset.pageMenuReady==='true')return;top.dataset.pageMenuReady='true';const nav=top.querySelector('.nav');const lang=top.querySelector('.lang');if(!nav&&!lang)return;const button=document.createElement('button');button.className='menu-toggle';button.type='button';button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','site-menu');button.textContent='Menu ';const caret=document.createElement('span');caret.className='menu-toggle-caret';caret.setAttribute('aria-hidden','true');button.appendChild(caret);const panel=document.createElement('div');panel.className='menu-panel';panel.id='site-menu';if(nav){const navClone=nav.cloneNode(true);navClone.classList.add('menu-panel-nav');panel.appendChild(navClone);nav.remove()}if(lang){const langClone=lang.cloneNode(true);langClone.classList.add('menu-panel-lang');panel.appendChild(langClone);lang.remove()}top.append(button,panel);const close=()=>{button.setAttribute('aria-expanded','false');panel.classList.remove('is-open')};button.addEventListener('click',()=>{const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));panel.classList.toggle('is-open',!open)});document.addEventListener('click',(event)=>{if(!top.contains(event.target))close()})})();document.querySelectorAll('a[href]').forEach((link)=>{const href=link.getAttribute('href')||'';const match=href.match(/(?:^|\/)(privacy-policy|refund-policy|billing-policy)(?:\.html)?\/?$/);if(match)link.href=`/${location.pathname.split('/')[1]||'en'}/${match[1]}`});